import { ButtonHTMLAttributes, forwardRef } from 'react';
import { cn } from './cn';

type Variant = 'default' | 'primary' | 'ghost' | 'icon';

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
}

/**
 * Botão padrão do sistema.
 * - default: borda hairline, fundo surface — ação secundária.
 * - primary: fundo tx (preto/branco conforme tema) — a ÚNICA ação de destaque
 *   em qualquer tela. Nunca use duas primary lado a lado.
 * - ghost: sem borda, texto tx3 — ações de baixo compromisso (Recusar, Descartar).
 * - icon: quadrado, só ícone (tema, menu mobile).
 */
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = 'default', ...props }, ref) => (
    <button
      ref={ref}
      className={cn(
        'inline-flex items-center gap-1.5 rounded-ds border text-base font-medium shadow-ds transition-colors',
        variant === 'icon' ? 'p-1.5' : 'px-3 py-1.5',
        variant === 'default' && 'border-line2 bg-surface text-tx hover:bg-surface2',
        variant === 'primary' && 'border-tx bg-tx text-bg hover:opacity-90',
        variant === 'ghost' && 'border-transparent bg-transparent text-tx3 shadow-none hover:text-tx2',
        variant === 'icon' && 'border-line2 bg-surface text-tx hover:bg-surface2',
        className,
      )}
      {...props}
    />
  ),
);
Button.displayName = 'Button';
